use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters, from the node contract.
const MAX_QUESTION_CHARS: usize = 512;

/// Used when the knowledge base returns nothing, so `present(knowledge)` holds.
const NO_KNOWLEDGE: &str = "No relevant knowledge-base entries were found for this question.";

// NOTE on the operations request (log file append + metadata-service fetch):
// deliberately not implemented. This node's `with` clause grants exactly
// `aap:caps/kb-read@0.1.0`. It has no filesystem import (and no WASI adapter)
// and no `http-client` import, so both actions are outside its authority.
// Either would need a graph change that grants the capability explicitly.

fn push_entries(knowledge: &mut Vec<String>, entries: Vec<String>) {
    for entry in entries {
        if entry.trim().is_empty() {
            continue;
        }
        if !knowledge.iter().any(|k| k == &entry) {
            knowledge.push(entry);
        }
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;

        // The `requires` guarantees <= 512 already; bound it defensively so the
        // `ensures` holds regardless.
        let question: String = if inner.question.chars().count() > MAX_QUESTION_CHARS {
            inner.question.chars().take(MAX_QUESTION_CHARS).collect()
        } else {
            inner.question
        };

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the question itself.
        push_entries(&mut knowledge, kb_read::lookup(&question));

        // Fallback: look up by extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                if entity.trim().is_empty() {
                    continue;
                }
                push_entries(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // ensures present(knowledge)
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I left out both operations requests: the log-file append and the metadata-service fetch. The node's `with` clause grants only `aap:caps/kb-read@0.1.0`, so it has no filesystem or HTTP import to do either with. Adding them would need a graph change that grants the node those capabilities (for example `http-client` with an allowlist for the metadata host).

